from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from rest_framework.permissions import IsAuthenticated, HasModuleGrant, HasPermission

from .models import LeaveApplication, LeaveBalance
from .serializers import LeaveApplicationSerializer

class LeaveBalanceListView(APIView):
    permission_classes = [IsAuthenticated, HasModuleGrant("leave_elm")]

    def get(self, request):
        user_id = request.principal.user_id
        try:
            balance = LeaveBalance.objects.get(user_id=user_id)
        except LeaveBalance.DoesNotExist:
            # Create default ELM balances if none exist yet
            balance = LeaveBalance(
                user_id=user_id,
                cl=8,
                rh=2,
                scl=15,
                el=30,
                col=20,
                vl=60
            )
            balance.save()

        return Response(balance.to_dict(), status=status.HTTP_200_OK)

class LeaveApplicationListCreateView(APIView):
    permission_classes = [IsAuthenticated, HasModuleGrant("leave_elm")]

    def get(self, request):
        user_id = request.principal.user_id
        if "leave_elm.application.approve" in request.principal.permissions:
            applications = LeaveApplication.objects.all().order_by('-created_at')
        else:
            applications = LeaveApplication.objects.filter(user_id=user_id).order_by('-created_at')

        serializer = LeaveApplicationSerializer(applications, many=True)
        return Response(serializer.data, status=status.HTTP_200_OK)

    def post(self, request):
        if "leave_elm.application.apply" not in request.principal.permissions:
            return Response({"error": "Permission denied"}, status=status.HTTP_403_FORBIDDEN)

        serializer = LeaveApplicationSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save(user_id=request.principal.user_id)
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        else:
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class LeaveApplicationReviewView(APIView):
    permission_classes = [IsAuthenticated, HasModuleGrant("leave_elm")]

    def post(self, request, pk):
        if "leave_elm.application.approve" not in request.principal.permissions:
            return Response({"error": "Permission denied"}, status=status.HTTP_403_FORBIDDEN)

        application = LeaveApplication.objects.get(pk=pk)
        serializer = LeaveApplicationSerializer(application, data=request.data)
        if serializer.is_valid():
            serializer.save(status="APPROVED", reviewed_by=request.principal.user_id, review_remarks=request.data.get('review_remarks'))
            balance = LeaveBalance.objects.get(user_id=application.user_id)
            balance.used += application.days
            balance.save()
            return Response(serializer.data, status=status.HTTP_200_OK)
        else:
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)
