import { useState, useEffect } from 'react';
import { Container, Title, Card, Group, Stack, Text, Button, Select, TextInput, Textarea, Checkbox, Badge, SimpleGrid } from '@mantine/core';
import http from '../../../lib/http';
import useAuth from '../../../auth/AuthProvider';

const LeaveApplicationsPage = () => {
  const [leaveTypes, setLeaveTypes] = useState([]);
  const [applications, setApplications] = useState([]);
  const [balance, setBalance] = useState(null);
  const [formData, setFormData] = useState({
    leave_type: '',
    start_date: '',
    end_date: '',
    days: '',
    reason: '',
    is_station_leave: false,
    station_leave_address: ''
  });
  const { user } = useAuth();

  useEffect(() => {
    // Fetch leave types
    http.get('/leave/leave_types').then((res) => setLeaveTypes(res.data));

    // Fetch balance
    if (user) {
      http.get(`/leave/balances/${user.id}`).then((res) => setBalance(res.data));
    }

    // Fetch applications
    http.get('/leave/applications').then((res) => setApplications(res.data));
  }, []);

  const handleSubmit = async () => {
    try {
      await http.post('/leave/applications', formData);
      alert('Leave application submitted successfully!');
      window.location.reload();
    } catch (error) {
      console.error('Error submitting leave application:', error);
    }
  };

  return (
    <Container>
      <Title order={2}>Leave Applications</Title>

      {/* Balance */}
      {balance && (
        <Card shadow="sm" p="md">
          <Stack>
            <Text>Current Leave Balance: {balance}</Text>
          </Stack>
        </Card>
      )}

      {/* Leave Types */}
      <Card shadow="sm" p="md">
        <Select
          label="Leave Type"
          placeholder="Select leave type"
          value={formData.leave_type}
          onChange={(value) => setFormData({ ...formData, leave_type: value })}
          data={leaveTypes.map((type) => ({ value: type.code, label: type.name }))}
        />
      </Card>

      {/* Application Form */}
      <Card shadow="sm" p="md">
        <Stack>
          <TextInput
            label="Start Date"
            placeholder="YYYY-MM-DD"
            value={formData.start_date}
            onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
          />
          <TextInput
            label="End Date"
            placeholder="YYYY-MM-DD"
            value={formData.end_date}
            onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
          />
          <TextInput
            label="Days"
            type="number"
            value={formData.days}
            onChange={(e) => setFormData({ ...formData, days: e.target.value })}
          />
          <Textarea label="Reason" value={formData.reason} onChange={(e) => setFormData({ ...formData, reason: e.target.value })} />
          <Checkbox
            label="Station Leave"
            checked={formData.is_station_leave}
            onChange={() => setFormData({ ...formData, is_station_leave: !formData.is_station_leave })}
          />
          {formData.is_station_leave && (
            <TextInput
              label="Station Leave Address"
              value={formData.station_leave_address}
              onChange={(e) => setFormData({ ...formData, station_leave_address: e.target.value })}
            />
          )}
          <Button onClick={handleSubmit}>Submit Application</Button>
        </Stack>
      </Card>

      {/* Applications List */}
      <Title order={3}>Leave Applications</Title>
      <SimpleGrid cols={2} spacing="lg">
        {applications.map((app) => (
          <Card shadow="sm" p="md" key={app.id}>
            <Group>
              <Text>{app.user.name}</Text>
              <Badge variant="outline">{app.status}</Badge>
            </Group>
            <Text>Leave Type: {app.leave_type.name}</Text>
            <Text>Start Date: {app.start_date}</Text>
            <Text>End Date: {app.end_date}</Text>
            <Text>Days: {app.days}</Text>
            <Text>Reason: {app.reason}</Text>
          </Card>
        ))}
      </SimpleGrid>
    </Container>
  );
};

export default LeaveApplicationsPage;
