import { useState, useEffect } from 'react';
import { Container, Title, Card, Group, Stack, Text, Button, Badge, TextInput } from '@mantine/core';
import http from '../../../lib/http';

const LeaveApprovalsPage = () => {
  const [applications, setApplications] = useState([]);
  const [selectedApplicationId, setSelectedApplicationId] = useState(null);
  const [remarks, setRemarks] = useState('');

  useEffect(() => {
    const fetchApplications = async () => {
      try {
        const response = await http.get('/leave/applications');
        setApplications(response.data);
      } catch (error) {
        console.error('Error fetching leave applications:', error);
      }
    };

    fetchApplications();
  }, []);

  const handleApprove = async () => {
    if (!selectedApplicationId || !remarks) return;

    try {
      await http.post(`/leave/applications/${selectedApplicationId}/review`, { action: 'APPROVE', remarks });
      setSelectedApplicationId(null);
      setRemarks('');
      alert('Leave application approved successfully!');
    } catch (error) {
      console.error('Error approving leave application:', error);
    }
  };

  const handleReject = async () => {
    if (!selectedApplicationId || !remarks) return;

    try {
      await http.post(`/leave/applications/${selectedApplicationId}/review`, { action: 'REJECT', remarks });
      setSelectedApplicationId(null);
      setRemarks('');
      alert('Leave application rejected successfully!');
    } catch (error) {
      console.error('Error rejecting leave application:', error);
    }
  };

  return (
    <Container size="lg" p="md">
      <Title order={2}>Leave Approvals</Title>
      <Stack spacing="sm">
        {applications.map((app, index) => (
          <Card key={index} shadow="sm" padding="sm">
            <Group position="apart">
              <Text>{app.employee_name}</Text>
              <Badge color={app.status === 'PENDING' ? 'yellow' : 'green'}>{app.status}</Badge>
            </Group>
            <Stack spacing="xs">
              {app.leave_type} - {app.start_date} to {app.end_date}
              <Text>{app.reason}</Text>
            </Stack>
            <Button
              variant="outline"
              color={app.status === 'PENDING' ? 'yellow' : 'green'}
              onClick={() => setSelectedApplicationId(app.id)}
              disabled={app.status !== 'PENDING'}
            >
              {app.status === 'PENDING' ? 'Approve' : 'Reject'}
            </Button>
          </Card>
        ))}
      </Stack>

      <Group position="center" mt="lg">
        {selectedApplicationId && (
          <>
            <TextInput
              label="Remarks"
              value={remarks}
              onChange={(e) => setRemarks(e.target.value)}
            />
            <Group spacing="sm">
              <Button variant="outline" color="green" onClick={handleApprove}>
                Approve
              </Button>
              <Button variant="outline" color="red" onClick={handleReject}>
                Reject
              </Button>
            </Group>
          </>
        )}
      </Group>
    </Container>
  );
};

export default LeaveApprovalsPage;
